            let tid = pre.combiner.get_Responding_1();

            require(tid < pre.num_threads);
            require(!pre.combiner.req_is_none(tid));

            update combiner = CombinerState::Responding(pre.combiner.get_Responding_0(), tid + 1);
            remove slots -= [ tid => let r ];
