    #[verifier::exec_allows_no_decreases_clause]
    fn get_response(
        &self,
        slog: &NrLog<DT>,
        tid: ThreadId,
        req_id: Ghost<ReqId>,
        context_ghost: Tracked<FCClientRequestResponseGhost<DT>>,
